context:
The team added this helper for running API calls with bounded concurrency. It is used by a migration command where order matters because result index maps back to input rows. The worker may return 0, false, null, or an object; only thrown errors represent failure. The command supports continueOnError and AbortSignal.

```ts
export async function runBatch<T, R>(
  items: T[],
  worker: (item: T, signal?: AbortSignal) => Promise<R>,
  opts: { limit?: number; continueOnError?: boolean; signal?: AbortSignal } = {}
): Promise<R[]> {
  const limit = opts.limit || 4
  const results: R[] = []
  let active = 0
  let index = 0
  let done = false

  return new Promise((resolve, reject) => {
    const next = () => {
      if (done) return
      if (index === items.length && active === 0) {
        done = true
        resolve(results.filter(Boolean) as R[])
        return
      }
      while (active < limit && index < items.length) {
        const item = items[index++]
        active++
        worker(item, opts.signal).then((result) => {
          if (result) results.push(result)
          active--
          next()
        }).catch((err) => {
          if (opts.continueOnError) {
            results.push(null as unknown as R)
          } else {
            done = true
            reject(err)
          }
        })
      }
    }

    if (opts.signal) {
      opts.signal.addEventListener('abort', () => {
        done = true
        resolve(results)
      })
    }

    next()
  })
}
```

The first field report says a 200-row migration with limit=8 and continueOnError=true sometimes never exits after one API row fails. A second report says successful rows are mismatched with input rows when worker responses include false or 0.
